CREATE FUNCTION public.set_user_role(target_user uuid,new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF target_user=auth.uid() THEN RAISE EXCEPTION 'Ask another administrator to change your own role'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target_user) THEN RAISE EXCEPTION 'Account not found'; END IF; DELETE FROM public.user_roles WHERE user_id=target_user; INSERT INTO public.user_roles(user_id,role) VALUES(target_user,new_role); END $$;
REVOKE ALL ON FUNCTION public.set_user_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_user_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.validate_measurement_date() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.measurement_date<OLD.measurement_date THEN RAISE EXCEPTION 'Measurement date cannot precede the latest record'; END IF; RETURN NEW; END $$;
CREATE TRIGGER chronological_measurements BEFORE UPDATE ON public.wells FOR EACH ROW EXECUTE FUNCTION public.validate_measurement_date();